      {%- endset -%}
      {{ og_include('compose/box.html.j2', {'p': {'Class': 'flex h-full min-w-0 flex-1 items-end', 'Attrs': og_attrs(['title', og_coalesce([og_get(v_b, ['title']), og_get(v_b, ['label'])]), 'data-slot', 'bar'])}, 'children': c_1}) }}
    {%- endfor %}
