  {{ og_include('compose/box.html.j2', {'p': {'Class': 'flex min-w-0 items-end gap-2', 'Attrs': og_attrs(['role', 'img', 'aria-label', v_label, 'style', og_css(['height', v_height, 'px'])])}, 'children': c_2}) }}
